from collections import defaultdict
CELL = 32.0
cells: dict[tuple[int, int], list[Entity]] = defaultdict(list)

def insert(e: Entity) -> None:
    cells[(int(e.x // CELL), int(e.y // CELL))].append(e)

def near(x: float, y: float, r: float) -> list[Entity]:
    return [e
            for cy in range(int((y - r) // CELL), int((y + r) // CELL) + 1)
            for cx in range(int((x - r) // CELL), int((x + r) // CELL) + 1)
            for e in cells[(cx, cy)]
            if (e.x - x) ** 2 + (e.y - y) ** 2 <= r * r]

